  "Ethical_Stabilizers": {
    "is_used": "Yes",
    "explanation": "The European Court of Justice and the European Commission are presented as legal/administrative authorities upholding Brussels' right to set asylum quotas and enforcing compliance (e.g., ECJ dismissed complaints; Commission may seek fines), which frames them as actors maintaining rules, cohesion and justice within the EU system."
  },
  "Altruistic_Catalysts": {
