  },
  "Altruistic_Catalysts": {
    "is_used": "Yes",
    "explanation": "Journalist Jacques Pauw is framed as a challenger to the status quo: he \"alleges millions of dollars\" in corruption, \"has continued to hold public signings,\" and says the SSA is using legal action to distract from revelations. This positions him as an exposing critic/underdog driving accountability despite pushback."
  },
  "Overt_Aggressors": {
