{
  "Ethical_Stabilizers": {
    "is_used": "Yes",
    "explanation": "Iran’s foreign ministry is portrayed as defending established norms—it 'summoned the Swiss ambassador' and protested that the order 'went against human rights conventions,' positioning the ministry as invoking moral and legal authority to uphold rights."
  },
  "Altruistic_Catalysts": {
    "is_used": "No",
    "explanation": "The text does not frame any actor as a rebel, martyr, or underdog driving systemic change or sacrificing for a cause."
  },
  "Overt_Aggressors": {
    "is_used": "Yes",
    "explanation": "The U.S. president’s travel ban is framed as an antagonistic policy: quoted as 'based on false and discriminatory pretexts,' which casts the policy (and by extension its sponsor) as a source of unjust, hostile action—consistent with a 'bigot' or instigator framing."
  },
  "Deceptive_Subversives": {
    "is_used": "Yes",
    "explanation": "The description that the executive order 'was based on false ... pretexts' frames the policy as founded on falsehoods, which characterizes it as deceptive or misleading (a 'deceiver')."
  },
  "Institutional_Toxins": {
    "is_used": "No",
    "explanation": "The passage does not allege corruption or incompetence within an institution; it focuses on a diplomatic protest and accusations of discrimination and falsehood, not institutional malfeasance or failure."
  },
  "Marginalized_Sufferers": {
    "is_used": "Yes",
    "explanation": "People from Iran and six other Muslim nations are presented as the targets of the travel ban, implicitly cast as victims of discriminatory policy and thus framed as suffering or marginalized groups."
  }
}

