  "Ethical_Stabilizers": {
    "is_used": "Yes",
    "explanation": "Sen. John McCain is framed as a moral authority and protector of norms: chairman of the Armed Services Committee who publicly rebukes torture (“We will not waterboard”), is portrayed as consistent in opposing harsh interrogation, and his veteran status and experience of being tortured lend him guardian-like credibility."
  },
  "Altruistic_Catalysts": {
