  },
  "Deceptive_Subversives": {
    "is_used": "No",
    "explanation": "There is no depiction of covert manipulation, espionage, betrayal, or deliberate misinformation in the passage."
  },
  "Institutional_Toxins": {
    "is_used": "Yes",
    "explanation": "The campaign and its super PAC are portrayed as making repeated failures—'made so many mistakes,' 'lighting money on fire,' and Jeb as the 'poster boy for the impotent Republican establishment'—framing organizational failure and incompetence."
