{
  "Ethical_Stabilizers": {
    "is_used": "Yes",
    "explanation": "China (via spokesman Geng Shuang) is framed as a peacemaker/virtuous actor: language stresses \"peaceful development,\" \"win-win cooperation,\" \"open and inclusive,\" and urging non-politicized, non-exclusionary regional cooperation — all markers of an Ethical Stabilizer preserving harmony and norms."
  },
  "Altruistic_Catalysts": {
    "is_used": "No",
    "explanation": "The text contains no depiction of rebels, martyrs, or underdogs challenging the status quo or sacrificing for systemic change."
  },
