  "Ethical_Stabilizers": {
    "is_used": "Yes",
    "explanation": "The Kremlin is framed as an authority upholding legal order: phrases like \"warned supporters... not to hold unsanctioned rallies,\" and the spokesman's quote that such calls \"run counter to the legislation in force\" portray the state as enforcing laws and maintaining social order (a guardian/peacemaker function)."
  },
  "Altruistic_Catalysts": {
    "is_used": "No",
    "explanation": "The text notes Navalny is a \"long-time Kremlin critic\" but does not frame him as actively driving systemic change through sacrifice or heroic struggle (no language of martyrdom, rebellion, or underdog uplift)."
  },
  "Overt_Aggressors": {
    "is_used": "Yes",
    "explanation": "The narrative reports the state’s coercive actions—Navalny is \"detained\" and \"sentenced\" and the Kremlin warns organizers they \"will be prosecuted\"—framing government actors as visible enforcers applying punitive power against opponents (instigator/tyrannical function)."
  },
  "Deceptive_Subversives": {
    "is_used": "No",
    "explanation": "There is no emphasis on secrecy, betrayal, covert plotting, espionage, or misinformation in the passage."
  },
  "Institutional_Toxins": {
    "is_used": "No",
    "explanation": "Although state institutions are taking punitive actions, the text does not characterize them as corrupt or incompetent; it reports official legal steps without language of internal decay or wrongdoing."
  },
  "Marginalized_Sufferers": {
    "is_used": "Yes",
    "explanation": "Alexei Navalny is presented as a detained opposition leader who will \"miss a campaign rally,\" positioning him (and implicitly his supporters) as subject to punitive measures and political exclusion—a victim/ marginalized sufferer framing."
  }
}

