  "Deceptive_Subversives": {
    "is_used": "Yes",
    "explanation": "The former mayor Ali al-Hujeiri is reported arrested 'in connection with' and 'accused of collusion with the Nusra Front,' framing him as a possible conspirator/traitor who secretly cooperated with militant actors."
  },
  "Institutional_Toxins": {
    "is_used": "No",
    "explanation": "While an official is accused of collusion, the piece frames this as alleged betrayal rather than as generic corruption or institutional incompetence; there is no explicit depiction of systemic abuse or broad institutional failure."
